app2.post(["/api/upload", "/api/upload.php"], requirePermission("media:upload"), async (req, res) => {
  try {
    const { image, name } = req.body;
    if (!image || typeof image !== "string") {
      return res.status(400).json({ error: "No image payload provided" });
    }
    let base64Data = image;
    let ext = "jpg";
    if (image.includes("base64,")) {
      const parts = image.split("base64,");
      const mimeMatch = parts[0].match(/:(.*?);/);
      if (mimeMatch && mimeMatch[1]) {
        const mime = mimeMatch[1].toLowerCase();
        if (mime === "image/png") ext = "png";
        else if (mime === "image/webp") ext = "webp";
        else if (mime === "image/jpeg" || mime === "image/jpg") ext = "jpg";
        else {
          return res.status(400).json({ error: "Unsupported media type. Only JPG, PNG, and WebP images are allowed." });
        }
      }
      base64Data = parts[1];
    }
    const buffer = Buffer.from(base64Data, "base64");
    if (buffer.length > 3 * 1024 * 1024) {
      return res.status(400).json({ error: "Image file exceeds maximum allowable size (3MB)." });
    }
    const headerHex = buffer.slice(0, 4).toString("hex");
    const isJpeg = headerHex.startsWith("ffd8ff");
    const isPng = headerHex === "89504e47";
    const isRiff = headerHex === "52494646" && buffer.subarray(8, 12).toString() === "WEBP";
    if (!isJpeg && !isPng && !isRiff) {
      return res.status(400).json({ error: "File signature verification failed. Only authentic image files are allowed." });
    }
    ext = isJpeg ? "jpg" : isPng ? "png" : "webp";
    const sanitizedName = typeof name === "string" ? name.replace(/[^a-zA-Z0-9_-]/g, "").substring(0, 40) : "scrap";
    const fileName = `${sanitizedName}_${Date.now()}_${Math.random().toString(36).substring(2, 7)}.${ext}`;
    const publicPath = path3.join(publicUploadsDir, fileName);
    if (cloudStorageEnabled()) {
      await mediaBucket().file("uploads/" + fileName).save(buffer, { resumable: false, metadata: { contentType: "image/" + (ext === "jpg" ? "jpeg" : ext), metadata: { firebaseStorageDownloadTokens: randomUUID2() } } });
    } else fs2.writeFileSync(publicPath, buffer);
    const fileUrl = `/uploads/${fileName}`;
    return res.json({
      success: true,
      url: fileUrl,
      fileName,
      fileSize: (buffer.length / 1024).toFixed(1) + " KB",
      mimeType: `image/${ext === "jpg" ? "jpeg" : ext}`
    });
  } catch (err) {
    console.error("Error uploading image:", err);
    return res.status(500).json({ error: "Failed to save image file on server.", details: err.message });
  }
});
