async function startServer() {
  const isProduction = process.env.NODE_ENV === "production";
  if (!isProduction) {
    console.log("\u{1F680} Starting Vite dev server in middleware mode with SSR...");
    const { createServer: createViteServer } = await import("vite");
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: "custom"
    });
    app2.use(vite.middlewares);
    app2.use("*", async (req, res, next) => {
      const url = req.originalUrl;
      const pathname = req.path;
      if (pathname.startsWith("/api") || pathname.startsWith("/uploads") || pathname.startsWith("/@") || path3.extname(pathname) !== "") {
        return next();
      }
      try {
        const rawTemplate = fs2.readFileSync(path3.resolve(process.cwd(), "index.html"), "utf-8");
        const transformedTemplate = await vite.transformIndexHtml(url, rawTemplate);
        const isPreview = req.query?.preview === "true" || req.query?.preview === "1";
        const previewToken = req.query?.token || req.query?.preview_token || void 0;
        const currentUser = req.user || void 0;
        const result = await renderSsrPage(url, transformedTemplate, {
          preview: isPreview,
          previewToken,
          user: currentUser
        });
        if (result.redirectUrl) {
          return res.redirect(result.statusCode, result.redirectUrl);
        }
        return res.status(result.statusCode).header("Cache-Control", "no-store").header("Content-Type", "text/html; charset=utf-8").send(result.html);
      } catch (err) {
        vite.ssrFixStacktrace(err);
        console.error("SSR dev error:", err);
        return res.status(500).end(err.stack);
      }
    });
  } else {
    console.log("\u{1F4E6} Starting Production Express server with SSR...");
    const distPath = path3.join(process.cwd(), "dist", "client");
    app2.use("/assets", express.static(path3.join(distPath, "assets"), { immutable: true, maxAge: "1y" }));
    app2.get(["/server.cjs", "/server.cjs.map", "/index.html", "/spa-shell.html"], (_req, res) => res.sendStatus(404));
    app2.use("*", async (req, res, next) => {
      const url = req.originalUrl;
      const pathname = req.path;
      if (pathname.startsWith("/api") || pathname.startsWith("/uploads") || path3.extname(pathname) !== "") {
        return next();
      }
      try {
        const templatePath = path3.join(distPath, "index.html");
        const template = fs2.existsSync(templatePath) ? fs2.readFileSync(templatePath, "utf-8") : fs2.readFileSync(path3.resolve(process.cwd(), "index.html"), "utf-8");
        const isPreview = req.query?.preview === "true" || req.query?.preview === "1";
        const previewToken = req.query?.token || req.query?.preview_token || void 0;
        const currentUser = req.user || void 0;
        const result = await renderSsrPage(url, template, {
          preview: isPreview,
          previewToken,
          user: currentUser
        });
        if (result.redirectUrl) {
          return res.redirect(result.statusCode, result.redirectUrl);
        }
        return res.status(result.statusCode).header("Cache-Control", "no-store").header("Content-Type", "text/html; charset=utf-8").send(result.html);
      } catch (err) {
        console.error("SSR production error:", err);
        return res.status(500).send("Internal Server Error");
      }
    });
  }
  app2.use("/api", (_req, res) => res.status(404).json({ error: "Not found" }));
  app2.use((err, _req, res, _next) => {
    if (err?.type === "entity.too.large") return res.status(413).json({ error: "Request too large. Images must be 3 MB or smaller." });
    console.error("Request failed:", err);
    return res.status(500).json({ error: "Request failed. Please retry." });
  });
  if (process.env.VERCEL !== "1") app2.listen(PORT, "0.0.0.0", () => {
    console.log(`\u2705 Shera Scrap Server running on http://0.0.0.0:${PORT}`);
  });
}
